import pkg_resources
import subprocess
import sys


def main():
    tests_folder = pkg_resources.resource_filename(
        'taf.ul.log_collection', 'robot_tests')

    robot_args = sys.argv[1:] if len(sys.argv) > 1 else []
    if "-V" not in robot_args and "--variable" not in robot_args:
        raise Exception(f"ERROR: Tests need to be started with testline configuration. Given Args: {robot_args}")
    else:
        subprocess.run(['robot'] + robot_args + [tests_folder], check=False)


if __name__ == '__main__':
    main()
